mapper.update:
UPDATE yak_wf_instance
SET state = #{runningState},
    start_time = COALESCE(start_time, #{startTime}),
    lock_version = lock_version + 1
WHERE id = #{instanceId}
  AND state = #{pendingState}

UPDATE yak_wf_instance
SET stop_requested = 1,
    state = CASE
      WHEN state IN

        #{state}

      THEN #{stoppingState}
      ELSE state
    END,
    lock_version = lock_version + 1
WHERE id = #{instanceId}
  AND state NOT IN

    #{state}
